const u32 x86i_count = sizeof x86i_tab / sizeof x86i_tab[0];

/* The entry named n (without its leading underscore), or -1. The table is sorted by name. */
int x86i_find(const char *n)
{
    int lo = 0, hi = (int)x86i_count - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2, c = strcmp(n, x86i_tab[mid].name);
        if (c == 0)
            return mid;
        if (c < 0)
            hi = mid - 1;
        else
            lo = mid + 1;
    }
    return -1;
}
